	private static void assertProbeHeap(Class<?> probeClass) {
		if (!probeClass.desiredAssertionStatus()) {
			throw new AssertionError("The child process must enable Java assertions");
		}
		long maxHeapBytes = Runtime.getRuntime().maxMemory();
		if (maxHeapBytes <= 0 || maxHeapBytes > CHILD_HEAP_BYTES) {
			throw new AssertionError("Expected a positive effective heap within the " + CHILD_HEAP_BYTES
					+ "-byte configured cap, got " + maxHeapBytes);
		}
		System.out.println("PROBE_HEAP configuredMaxHeapBytes=" + CHILD_HEAP_BYTES + " effectiveMaxHeapBytes="
				+ maxHeapBytes + " assertionsEnabled="
				+ probeClass.desiredAssertionStatus());
	}

	/**
	 * Runs repeated public store initialization and shutdown in a fresh, fixed-size heap. The default value store
	 * allocates two primitive {@code long[]} caches, each with at least {@link LmdbStoreConfig#VALUE_CACHE_SIZE}
	 * elements. A leaked store therefore retains at least {@code 2 * VALUE_CACHE_SIZE * Long.BYTES} per iteration; one
	 * more than the heap-to-cache ratio exceeds the child heap even before counting object headers or other fields.
	 */
	public static final class Probe {
		private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();

		private Probe() {
		}

		public static void main(String[] args) throws Exception {
			assertProbeHeap(Probe.class);
			File root = Path.of(args[0]).toFile();
			int iterations = Integer.parseInt(args[1]);
			boolean backgroundWork = Boolean.parseBoolean(args[2]);
			for (int iteration = 0; iteration < iterations; iteration++) {
				LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
						.setDirectAdjacencyEnabled(true)
						.setDirectAdjacencyMaxBytes(LmdbStoreConfig.DIRECT_ADJACENCY_MIN_EXPLICIT_BYTES)
						.setDirectAdjacencyBuildOnStart(backgroundWork);
				LmdbStore store = new LmdbStore(new File(root, "store-" + iteration), config);
				SailRepository repository = new SailRepository(store);
				try {
					repository.init();
					if (backgroundWork) {
						writeOneStatement(repository, iteration);
						if (!store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS)) {
							throw new AssertionError(
									"Background direct-adjacency work did not publish the current revision");
						}
					}
				} finally {
					repository.shutDown();
				}
			}
			System.out.println(PROBE_COMPLETE + " iterations=" + iterations + " backgroundWork=" + backgroundWork);
		}

		private static void writeOneStatement(SailRepository repository, int iteration) {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(VALUES.createIRI("urn:lifecycle:subject:" + iteration),
						VALUES.createIRI("urn:lifecycle:predicate"), VALUES.createLiteral("value-" + iteration));
			}
		}
	}

